// Sort: ball sort and water sort. Levels are generated by reverse moves from a solved state (always solvable).
// Tap a tube, then another tube. Undo, restart, an extra empty tube power-up, more colours each level.
import { background, Bag, byDiff, createStage, emoji, keys, loop, Particles, pointer, roundRect, Shake, text, type Engine, type GameEnv, type GameHandle } from '../kit'
import { applyMove, genSort, isSortSolved, moveCount, type Tubes } from '../logic/sort'
import { flipFrom, genOrder, isOrdered, parFor, swapAt, type OrderKind } from '../logic/sort-order'

let W = 800
let H = 450

const orderKind = (name: string): OrderKind | null =>
  /pancake flip/i.test(name) ? 'flip' : /bubble sorter/i.test(name) ? 'bubble' : /bookshelf|card deck|library return|archive clerk/i.test(name) ? 'swap' : null

// ---------- ordering puzzles: swap / neighbour swap / pancake flip ----------

function startOrder(env: GameEnv, kind: OrderKind): GameHandle {
  const hr = env.host.getBoundingClientRect()
  if (hr.height > hr.width * 1.15) {
    W = 450
    H = 800
  } else {
    W = 800
    H = 450
  }
  const t = env.theme
  const st = createStage(env.host, W, H)
  const c = st.ctx
  const k = keys()
  const bag = new Bag()
  const fx = new Particles()
  const shake = new Shake()
  const ptr = pointer(st)
  bag.add(() => ptr.dispose())
  const por = W < 600
  const levels = byDiff(env, 6, 8, 10)
  let level = 1
  let score = 0
  let row: number[] = []
  let start: number[] = []
  let pos: { x: number; y: number }[] = []
  let par = 0
  let moves = 0
  let sel = -1
  let cursor = 0
  let tt = 0
  let pause = 0
  let over = false
  let msg = ''
  const n = () => row.length
  const rank = (v: number) => (kind === 'flip' ? n() - v : v + 1)
  // slot geometry
  const geo = () => {
    const N = n()
    if (kind === 'flip') {
      const ph = Math.min(46, Math.floor((H - (por ? 280 : 170)) / N))
      return { ph, bw: 0, baseY: H - (por ? 200 : 90) }
    }
    const bw = Math.min(74, Math.floor((W - 30) / N) - 6)
    return { ph: 0, bw, baseY: H - (por ? 190 : 80) }
  }
  const slotXY = (i: number) => {
    const g = geo()
    if (kind === 'flip') return { x: W / 2, y: g.baseY - i * g.ph }
    const step = g.bw + 6
    return { x: W / 2 - ((n() - 1) * step) / 2 + i * step, y: g.baseY }
  }
  const hud = () => {
    env.score(score)
    env.status(`Level ${level}/${levels} · ${moves} moves (par ${par})`)
  }
  const build = () => {
    const N = Math.min(kind === 'flip' ? 8 : 10, 4 + level + (env.difficulty === 2 ? 1 : 0))
    row = genOrder(env.rng, N)
    start = row.slice()
    par = parFor(kind, row)
    moves = 0
    sel = -1
    cursor = 0
    pos = row.map((_, i) => slotXY(i))
    hud()
  }
  const win = () => {
    score += 100 * level + Math.max(0, par * 2 - moves) * 5
    env.sfx('win')
    shake.kick(4)
    for (let i = 0; i < n(); i++) fx.burst(slotXY(i).x, slotXY(i).y, t.blocks[row[i] % t.blocks.length], 8, 200, 3)
    if (level >= levels) {
      over = true
      msg = 'All sorted!'
      pause = 1.5
    } else {
      msg = 'Sorted!'
      pause = 1.2
    }
    hud()
  }
  const act = (i: number) => {
    if (pause > 0 || over || i < 0 || i >= n()) return
    if (kind === 'flip') {
      row = flipFrom(row, i)
      moves++
      env.sfx('move')
    } else if (sel < 0) {
      sel = i
      env.sfx('click')
      return
    } else if (sel === i) {
      sel = -1
      return
    } else if (kind === 'bubble' && Math.abs(sel - i) !== 1) {
      sel = i
      env.sfx('click')
      return
    } else {
      row = swapAt(row, sel, i)
      sel = -1
      moves++
      env.sfx('move')
    }
    hud()
    if (isOrdered(row)) win()
  }
  const reset = () => {
    if (pause > 0) return
    row = start.slice()
    moves = 0
    sel = -1
    hud()
  }
  const hit = (p: { x: number; y: number }) => {
    const g = geo()
    for (let i = n() - 1; i >= 0; i--) {
      const s = slotXY(i)
      if (kind === 'flip') {
        if (Math.abs(p.y - s.y) < g.ph / 2 && Math.abs(p.x - s.x) < W * 0.4) return i
      } else if (Math.abs(p.x - s.x) < (g.bw + 6) / 2 && p.y < g.baseY + 30 && p.y > g.baseY - (por ? 400 : 330)) return i
    }
    return -1
  }
  const rb = () => ({ x: W / 2 - 60, y: H - (por ? 110 : 44), w: 120, h: 38 })
  ptr.onDown((p) => {
    if (p.button === 2) return
    const b = rb()
    if (p.x >= b.x && p.x < b.x + b.w && p.y >= b.y && p.y < b.y + b.h) return reset()
    const i = hit(p)
    if (i >= 0) {
      cursor = i
      act(i)
    }
  })
  k.onKey((e) => {
    if (e.code === 'ArrowLeft' || e.code === 'KeyA') cursor = Math.max(0, cursor - 1)
    else if (e.code === 'ArrowRight' || e.code === 'KeyD') cursor = Math.min(n() - 1, cursor + 1)
    else if (e.code === 'ArrowUp' || e.code === 'KeyW') cursor = Math.min(n() - 1, cursor + 1)
    else if (e.code === 'ArrowDown' || e.code === 'KeyS') cursor = Math.max(0, cursor - 1)
    else if (e.code === 'Space' || e.code === 'Enter') act(cursor)
    else if (e.code === 'KeyR') reset()
  })
  build()
  const update = (dt: number) => {
    tt += dt
    fx.update(dt, 200)
    shake.update(dt)
    const a = Math.min(1, dt * 14)
    row.forEach((_, i) => {
      const s = slotXY(i)
      const p = pos[i] ?? (pos[i] = { ...s })
      p.x += (s.x - p.x) * a
      p.y += (s.y - p.y) * a
    })
    if (pause > 0) {
      pause -= dt
      if (pause <= 0) {
        if (over) env.end({ score, won: true, text: `Solved all ${levels} levels` })
        else {
          level++
          build()
        }
      }
    }
  }
  const draw = () => {
    c.clearRect(0, 0, W, H)
    c.save()
    background(c, W, H, t, 40, env.seed)
    shake.apply(c)
    text(c, `LEVEL ${level}/${levels}`, 74, 28, { size: 12, color: t.accent, align: 'left' })
    text(c, `${moves} MOVES`, W - (por ? 80 : 110), 28, { size: 10, color: t.fg })
    emoji(c, t.hero, 34, 36, 38, Math.sin(tt * 4) * 0.12)
    const g = geo()
    const N = n()
    if (kind === 'flip') {
      c.fillStyle = (t.fg + '1f')
      c.fillRect(W / 2 - W * 0.3, g.baseY + g.ph / 2, W * 0.6, 8)
    } else {
      c.fillStyle = (t.fg + '24')
      c.fillRect(20, g.baseY + 4, W - 40, 8)
    }
    const maxH = por ? 300 : 250
    for (let i = 0; i < N; i++) {
      const v = row[i]
      const p = pos[i] ?? slotXY(i)
      const col = t.blocks[v % t.blocks.length]
      const hot = sel === i
      const isCur = cursor === i && !ptr.active
      if (kind === 'flip') {
        const w = 70 + (rank(v) / N) * (W * 0.5 - 70)
        roundRect(c, p.x - w / 2, p.y - g.ph / 2 + 2, w, g.ph - 4, g.ph / 2.4, col, isCur ? t.accent : 'rgba(0,0,0,.35)', isCur ? 3 : 1.5)
        emoji(c, t.items[v % t.items.length], p.x - w / 2 + 18, p.y, g.ph * 0.6)
        text(c, String(rank(v)), p.x, p.y, { size: 10, color: '#fff' })
      } else {
        const h = 40 + (rank(v) / N) * (maxH - 40)
        const lift = hot ? -16 + Math.sin(tt * 8) * 2 : 0
        roundRect(c, p.x - g.bw / 2, p.y - h + lift, g.bw, h, 6, col, hot ? t.accent : isCur ? t.fg : 'rgba(0,0,0,.35)', hot || isCur ? 3 : 1.5)
        c.fillStyle = (t.fg + '38')
        c.fillRect(p.x - g.bw / 2 + 4, p.y - h + lift + 4, 5, h - 8)
        emoji(c, t.items[v % t.items.length], p.x, p.y - h + lift - 14, Math.min(34, g.bw * 0.7))
        text(c, String(rank(v)), p.x, p.y - 14 + lift, { size: 11, color: '#fff' })
      }
    }
    fx.draw(c)
    c.restore()
    const b = rb()
    roundRect(c, b.x, b.y, b.w, b.h, 12, 'rgba(0,0,0,.4)', t.accent2, 2)
    text(c, '↻ RESET', b.x + b.w / 2, b.y + b.h / 2, { size: 10, color: t.fg })
    if (tt < 5) {
      c.globalAlpha = tt < 4.4 ? 1 : 1 - (tt - 4.4) / 0.6
      text(c, env.name, W / 2, por ? 70 : 62, { size: por ? 10 : 12, color: t.accent })
      text(c, kind === 'flip' ? 'TAP a pancake: it and all above flip over · biggest at the bottom' : kind === 'bubble' ? 'SWAP two neighbours · smallest on the left' : 'TAP two items to swap them · smallest on the left', W / 2, por ? 84 : 78, { size: por ? 6 : 8, color: t.fg })
      c.globalAlpha = 1
    }
    if (pause > 0) {
      c.fillStyle = 'rgba(0,0,0,.4)'
      c.fillRect(0, H / 2 - 40, W, 80)
      text(c, msg, W / 2, H / 2, { size: 26, color: t.good, shadow: t.good })
    }
  }
  const lp = loop(update, draw)
  return {
    pause: (p) => lp.pause(p),
    destroy() {
      lp.stop()
      k.dispose()
      bag.dispose()
      st.dispose()
    },
  }
}

const engine: Engine = {
  start(env) {
    const ok = orderKind(env.name)
    if (ok) return startOrder(env, ok)
    const hr = env.host.getBoundingClientRect()
    if (hr.height > hr.width * 1.15) {
      W = 450
      H = 800
    } else {
      W = 800
      H = 450
    }
    const { theme: t } = env
    const st = createStage(env.host, W, H)
    const c = st.ctx
    const k = keys()
    const bag = new Bag()
    const fx = new Particles()
    const shake = new Shake()
    const ptr = pointer(st)
    const por = W < 600
    const label = `${env.name} ${env.desc}`
    const multi = /water|liquid|pour|potion|juice|spice|ink|fill/i.test(label)
    const levels = byDiff(env, 7, 9, 10)
    const cap = 4
    let level = 1
    let score = 0
    let tubes: Tubes = []
    let initial: Tubes = []
    let par = 0
    let hist: Tubes[] = []
    let moves = 0
    let sel = -1
    let cursor = 0
    let extra = 0
    let hidden: number[] = []
    const flying: { fx: number; fy: number; tx: number; ty: number; t: number; d: number; to: number; color: string; em: string }[] = []
    let tt = 0
    let over = false
    let pause = 0
    let after: (() => void) | null = null
    let msg = ''
    let msgT = 0
    let doneSet = new Set<number>()
    let rects: { x: number; y: number; w: number; h: number }[] = []
    let bs = 40
    let shakeT = -1

    const colorOf = (n: number) => t.blocks[(n + Math.floor(n / t.items.length)) % t.blocks.length]
    const itemOf = (n: number) => t.items[n % t.items.length]
    const copy = (x: Tubes) => x.map((a) => a.slice())

    const layout = () => {
      const n = tubes.length
      const cols = por ? Math.min(n, 5) : n <= 8 ? n : Math.ceil(n / 2)
      const rows = Math.ceil(n / cols)
      const top = por ? 90 : 70
      const availH = H - top - (por ? 190 : 110)
      const tw0 = Math.min(78, (W - 24) / cols - 10)
      bs = Math.floor(Math.min(tw0 - 10, (availH / rows - 36) / cap))
      const tw = bs + 12
      const th = cap * bs + 14
      const gapX = (W - 24 - cols * tw) / Math.max(1, cols)
      const rowGap = (availH - rows * th) / Math.max(1, rows)
      rects = []
      for (let i = 0; i < n; i++) {
        const r = Math.floor(i / cols)
        const inRow = Math.min(cols, n - r * cols)
        const rowW = inRow * tw + (inRow - 1) * gapX
        const x = (W - rowW) / 2 + (i - r * cols) * (tw + gapX)
        rects.push({ x, y: top + 30 + r * (th + Math.max(34, rowGap)), w: tw, h: th })
      }
    }
    const slot = (ti: number, idx: number) => {
      const r = rects[ti]
      return { x: r.x + r.w / 2, y: r.y + r.h - 7 - bs * (idx + 0.5) }
    }

    const build = () => {
      const colors = Math.min(12, 2 + level + (env.difficulty === 2 ? 1 : 0))
      const empty = env.difficulty === 2 && level >= 6 ? 1 : 2
      const lv = genSort(env.rng, { colors, cap, empty, multi })
      tubes = lv.tubes
      initial = copy(tubes)
      par = lv.solution.length
      hist = []
      moves = 0
      sel = -1
      cursor = 0
      extra = byDiff(env, 2, 1, 1)
      hidden = tubes.map(() => 0)
      flying.length = 0
      doneSet = new Set()
      layout()
      hud()
    }
    const hud = () => {
      env.score(score)
      env.status(`Level ${level}/${levels} · ${moves} moves · ➕${extra}`)
    }

    const checkTube = (i: number) => {
      const tb = tubes[i]
      if (tb.length === cap && tb.every((x) => x === tb[0]) && !doneSet.has(i)) {
        doneSet.add(i)
        const r = rects[i]
        fx.burst(r.x + r.w / 2, r.y + r.h / 2, colorOf(tb[0]), 18, 170, 3)
        env.sfx('point')
      }
    }
    const win = () => {
      const bonus = Math.max(0, par * 2 - moves) * 4
      score += 100 * level + bonus
      env.sfx('win')
      shake.kick(4)
      for (let i = 0; i < rects.length; i++) if (tubes[i].length) fx.burst(rects[i].x + rects[i].w / 2, rects[i].y, colorOf(tubes[i][0]), 12, 220, 3)
      if (level >= levels) {
        over = true
        msg = 'All sorted!'
        msgT = 99
        pause = 1.5
        after = () => env.end({ score, won: true, text: `Solved all ${levels} levels` })
      } else {
        msg = 'Sorted!'
        msgT = 1.2
        pause = 1.3
        level++
        after = build
      }
      hud()
    }

    const doMove = (from: number, to: number) => {
      const n = moveCount(tubes, cap, from, to, multi)
      if (!n) {
        shakeT = 0.25
        env.sfx('hit')
        return false
      }
      hist.push(copy(tubes))
      const color = tubes[from][tubes[from].length - 1]
      const fromLen = tubes[from].length
      const toLen = tubes[to].length
      applyMove(tubes, cap, from, to, multi)
      moves++
      env.sfx('move')
      for (let i = 0; i < n; i++) {
        const a = slot(from, fromLen - 1 - i)
        const b = slot(to, toLen + i)
        hidden[to]++
        flying.push({ fx: a.x, fy: a.y, tx: b.x, ty: b.y, t: -i * 0.07, d: 0.26, to, color: colorOf(color), em: itemOf(color) })
      }
      return true
    }
    const tap = (i: number) => {
      if (pause > 0 || over) return
      if (sel < 0) {
        if (tubes[i].length) {
          sel = i
          env.sfx('click')
        }
      } else if (sel === i) {
        sel = -1
      } else {
        const from = sel
        sel = -1
        if (!doMove(from, i) && tubes[i].length) sel = i
        hud()
      }
    }
    const undo = () => {
      const s = hist.pop()
      if (!s || pause > 0 || over) return
      tubes = s
      moves = Math.max(0, moves - 1)
      hidden = tubes.map(() => 0)
      flying.length = 0
      doneSet = new Set()
      tubes.forEach((_, i) => checkTube(i))
      sel = -1
      layout()
      env.sfx('power')
      hud()
    }
    const addTube = () => {
      if (extra <= 0 || pause > 0 || over) return
      extra--
      hist.push(copy(tubes))
      tubes.push([])
      hidden.push(0)
      layout()
      env.sfx('power')
      hud()
    }
    const restart = () => {
      if (pause > 0 || over) return
      tubes = copy(initial)
      hist = []
      moves = 0
      sel = -1
      hidden = tubes.map(() => 0)
      flying.length = 0
      doneSet = new Set()
      extra = byDiff(env, 2, 1, 1)
      layout()
      env.sfx('click')
      hud()
    }
    const btns = () => {
      const y = H - (por ? 150 : 52)
      const w = por ? 130 : 150
      const gap = por ? (W - 3 * w) / 4 : 20
      const x0 = por ? gap : W / 2 - (3 * w + 2 * gap) / 2
      return [
        { x: x0, y, w, h: 44, label: '↶ UNDO', fn: undo },
        { x: x0 + w + gap, y, w, h: 44, label: `＋ TUBE ${extra}`, fn: addTube },
        { x: x0 + 2 * (w + gap), y, w, h: 44, label: '↻ RESET', fn: restart },
      ]
    }
    ptr.onDown((p) => {
      if (p.button === 2) return
      for (const b of btns()) if (p.x >= b.x && p.x < b.x + b.w && p.y >= b.y && p.y < b.y + b.h) return b.fn()
      for (let i = 0; i < rects.length; i++) {
        const r = rects[i]
        if (p.x >= r.x - 8 && p.x < r.x + r.w + 8 && p.y >= r.y - bs && p.y < r.y + r.h + 8) return tap(i)
      }
    })
    k.onKey((e) => {
      if (e.code === 'KeyU' || e.code === 'KeyZ' || e.code === 'Backspace') undo()
      else if (e.code === 'KeyT' || e.code === 'KeyE') addTube()
      else if (e.code === 'KeyR') restart()
      else if (e.code === 'ArrowLeft' || e.code === 'KeyA') cursor = (cursor + tubes.length - 1) % tubes.length
      else if (e.code === 'ArrowRight' || e.code === 'KeyD') cursor = (cursor + 1) % tubes.length
      else if (e.code === 'Space' || e.code === 'Enter') tap(cursor)
      else if (/^Digit[1-9]$/.test(e.code) && Number(e.code.slice(5)) <= tubes.length) tap(Number(e.code.slice(5)) - 1)
    })

    build()

    const update = (dt: number) => {
      tt += dt
      fx.update(dt, 200)
      shake.update(dt)
      msgT -= dt
      shakeT -= dt
      for (const f of flying) f.t += dt
      for (let i = flying.length - 1; i >= 0; i--) {
        if (flying[i].t >= flying[i].d) {
          const f = flying[i]
          hidden[f.to] = Math.max(0, (hidden[f.to] ?? 0) - 1)
          fx.burst(f.tx, f.ty, f.color, 4, 70, 2)
          flying.splice(i, 1)
          if (!flying.some((q) => q.to === f.to)) checkTube(f.to)
          if (!flying.length && !over && isSortSolved(tubes, cap) && pause <= 0) win()
        }
      }
      if (pause > 0) {
        pause -= dt
        if (pause <= 0 && after) {
          const f = after
          after = null
          f()
        }
      }
    }

    const draw = () => {
      c.clearRect(0, 0, W, H)
      c.save()
      background(c, W, H, t, 40, env.seed)
      shake.apply(c)
      text(c, `LEVEL ${level}/${levels}`, 74, 28, { size: 12, color: t.accent, align: 'left' })
      text(c, `${moves} MOVES`, W - (por ? 80 : 110), 28, { size: 10, color: t.fg })
      emoji(c, t.hero, 34, 36, 38, Math.sin(tt * 4) * 0.12)
      for (let i = 0; i < rects.length; i++) {
        const r = rects[i]
        const tb = tubes[i]
        const isSel = sel === i
        const shk = shakeT > 0 && (isSel || cursor === i) ? Math.sin(shakeT * 90) * 3 : 0
        c.save()
        c.translate(shk, 0)
        const done = doneSet.has(i) && tb.length === cap
        roundRect(c, r.x, r.y, r.w, r.h, r.w / 2.5, 'rgba(255,255,255,.07)', done ? t.good : isSel ? t.accent : 'rgba(255,255,255,.35)', isSel || done ? 3 : 2)
        if (done) {
          c.shadowColor = t.good
          c.shadowBlur = 14
          c.strokeStyle = t.good
          c.stroke()
          c.shadowBlur = 0
        }
        if (!isSel && cursor === i && !ptr.active) {
          c.fillStyle = t.accent
          c.fillRect(r.x + r.w / 2 - 6, r.y + r.h + 10, 12, 4)
        }
        const shown = tb.length - (hidden[i] ?? 0)
        for (let j = 0; j < shown; j++) {
          const p = slot(i, j)
          const lift = isSel && j === tb.length - 1 ? -bs * 0.9 - 6 + Math.sin(tt * 8) * 2 : 0
          if (multi) {
            c.fillStyle = colorOf(tb[j])
            const top = j === shown - 1
            roundRect(c, r.x + 5, p.y - bs / 2 + lift, r.w - 10, bs + (top ? 0 : 1), top ? 5 : 0, colorOf(tb[j]))
            if (top) {
              c.fillStyle = 'rgba(255,255,255,.28)'
              c.fillRect(r.x + 8, p.y - bs / 2 + lift + 2, r.w - 16, 3)
            }
            if (j === 0 || tb[j - 1] !== tb[j]) emoji(c, itemOf(tb[j]), p.x, p.y + lift, bs * 0.5)
          } else {
            c.save()
            c.shadowColor = colorOf(tb[j])
            c.shadowBlur = 6
            c.fillStyle = colorOf(tb[j])
            c.beginPath()
            c.arc(p.x, p.y + lift, bs / 2 - 2, 0, 7)
            c.fill()
            c.restore()
            c.fillStyle = 'rgba(255,255,255,.35)'
            c.beginPath()
            c.arc(p.x - bs * 0.14, p.y + lift - bs * 0.16, bs * 0.1, 0, 7)
            c.fill()
            emoji(c, itemOf(tb[j]), p.x, p.y + lift + 1, bs * 0.52)
          }
        }
        c.restore()
      }
      for (const f of flying) {
        if (f.t < 0) continue
        const u = f.t / f.d
        const x = f.fx + (f.tx - f.fx) * u
        const y = f.fy + (f.ty - f.fy) * u - Math.sin(u * Math.PI) * bs * 1.6
        c.fillStyle = f.color
        c.beginPath()
        c.arc(x, y, bs / 2 - 2, 0, 7)
        c.fill()
        emoji(c, f.em, x, y + 1, bs * 0.52)
      }
      fx.draw(c)
      c.restore()
      for (const b of btns()) {
        const off = b.label.startsWith('＋') && extra <= 0
        roundRect(c, b.x, b.y, b.w, b.h, 12, off ? 'rgba(255,255,255,.06)' : 'rgba(0,0,0,.4)', off ? 'rgba(255,255,255,.15)' : t.accent2, 2)
        text(c, b.label, b.x + b.w / 2, b.y + b.h / 2, { size: por ? 9 : 10, color: off ? 'rgba(255,255,255,.35)' : t.fg })
      }
      if (tt < 3) {
        c.globalAlpha = tt < 2.4 ? 1 : 1 - (tt - 2.4) / 0.6
        text(c, env.name, W / 2, por ? 70 : 62, { size: por ? 10 : 12, color: t.accent })
        text(c, multi ? 'TAP a tube, then another · pour matching colours' : 'TAP a ball stack, then a tube · stack matching colours', W / 2, por ? 84 : 78, { size: por ? 6 : 8, color: t.fg })
        c.globalAlpha = 1
      }
      if (pause > 0) {
        c.fillStyle = 'rgba(0,0,0,.4)'
        c.fillRect(0, H / 2 - 40, W, 80)
        text(c, msg, W / 2, H / 2, { size: 26, color: t.good, shadow: t.good })
      }
    }

    const lp = loop(update, draw)
    return {
      pause: (p) => lp.pause(p),
      destroy() {
        lp.stop()
        k.dispose()
        ptr.dispose()
        bag.dispose()
        st.dispose()
      },
    }
  },
}

export default engine
